jQuery(document).ready(function(t){var e=[];t(".comment-like-count").each(function(){var n=t(this).attr("data-blog-id"),a=t(this).attr("data-comment-id");e.push("http://raulrebollos.com/sites/"+n+"http://raulrebollos.com/comments/"+a+"http://raulrebollos.com/likes")}),t.ajax({type:"GET",url:"https://public-api.wordpress.com/rest/v1/batch",dataType:"jsonp",data:"urls[]="+e.map(encodeURIComponent).join("&urls[]="),success:function(e){for(var n in e)if(!e[n].error_data){var a=n.split("http://raulrebollos.com/")[4],o=e[n].found;if(o<1)return;t("#comment-like-count-"+a).find(".like-count").hide().text(o).fadeIn()}},error:function(){}})});